using System;using System.IO;using System.Linq;using System.Reflection;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine.Rendering;using UnityEngine.Rendering.Universal;using MapTunnels.EditorTools;
public static class Rock132Diagnosis{
 static string Root=>Path.GetFullPath(Path.Combine(Application.dataPath,".."));static string Out=>Path.Combine(Root,"Evidence132Diagnosis");
 static void Check(bool ok,string s){if(!ok)throw new Exception(s);}
 public static void Run(){Directory.CreateDirectory(Out);try{EditorSceneManager.NewScene(NewSceneSetup.EmptyScene,NewSceneMode.Single);var rp=AssetDatabase.LoadAssetAtPath<UniversalRenderPipelineAsset>("Assets/Settings/PC_RPAsset.asset");GraphicsSettings.defaultRenderPipeline=rp;QualitySettings.renderPipeline=rp;RenderSettings.ambientMode=AmbientMode.Flat;RenderSettings.ambientLight=new Color(.06f,.065f,.075f);var result=MapTunnelBuilder.Build(Path.Combine(Root,"Input123Mine"),null,null,"CutRock131");Check(result.built,"formal product tunnel build "+result.message);
 var camera=new GameObject("review camera").AddComponent<Camera>();camera.clearFlags=CameraClearFlags.SolidColor;camera.backgroundColor=new Color(.025f,.03f,.04f);camera.fieldOfView=45;camera.nearClipPlane=.03f;var hero=new GameObject("position gauge").transform;hero.position=new Vector3(12,0,11.4f);var cut=result.root.GetComponent<MapTunnels.MapTunnelCutaway>();cut.hero=hero;cut.viewCamera=camera;
 var rails=new GameObject("Formal rail prefabs");for(int j=0;j<2;j++){var o=(GameObject)PrefabUtility.InstantiatePrefab(AssetDatabase.LoadAssetAtPath<GameObject>("Assets/Imported125-valid/small-mine_rail_straight.prefab"));o.transform.SetParent(rails.transform,false);o.transform.position=new Vector3(12,0,14-j*2);}
 var cart=(GameObject)PrefabUtility.InstantiatePrefab(AssetDatabase.LoadAssetAtPath<GameObject>("Assets/Imported125-valid/small-minecart.prefab"));cart.transform.SetParent(rails.transform,false);cart.transform.position=new Vector3(12,.14f,13.4f);
 var rock=(GameObject)PrefabUtility.InstantiatePrefab(AssetDatabase.LoadAssetAtPath<GameObject>("Assets/Imported131-valid/small-mine_cut_rock.prefab"));rock.transform.SetParent(rails.transform,false);rock.transform.SetPositionAndRotation(new Vector3(13.12f,0,11.4f),Quaternion.Euler(0,90,0));Physics.SyncTransforms();var rc=rock.GetComponent<BoxCollider>();Check(rc&&rc.bounds.min.x>12.8f,"rock shallow collider leaves central corridor");Check(!rc.bounds.Intersects(cart.GetComponent<Collider>().bounds),"cart corridor stays clear");var rockTarget=rock.GetComponent<Renderer>().bounds.center;var baseline=(GameObject)PrefabUtility.InstantiatePrefab(AssetDatabase.LoadAssetAtPath<GameObject>("Assets/Imported127-valid/small-mine_cut_rock.prefab"));baseline.transform.SetPositionAndRotation(rock.transform.position,rock.transform.rotation);baseline.SetActive(false);

 camera.transform.position=rockTarget+new Vector3(-1.5f,.3f,-1.3f);camera.transform.LookAt(rockTarget);typeof(MapTunnels.MapTunnelCutaway).GetMethod("LateUpdate",BindingFlags.NonPublic|BindingFlags.Instance).Invoke(cut,null);
 var originalCut=Shader.GetGlobalVector("_MapCutA");var renderers=result.root.GetComponentsInChildren<Renderer>();var rm=rock.GetComponent<Renderer>();var originalMat=rm.sharedMaterial;var tunnelRenderer=renderers.First(r=>r.name=="Tunnels");var tunnelMaterials=tunnelRenderer.sharedMaterials;var frameId=new Material(Shader.Find("Universal Render Pipeline/Unlit"));frameId.SetColor("_BaseColor",Color.cyan);var lights=UnityEngine.Object.FindObjectsByType<Light>(FindObjectsSortMode.None);var shadows=lights.Select(l=>l.shadows).ToArray();
 camera.aspect=1600f/900f;var originalPosition=rock.transform.position;
 var report=new Report{camera=camera.transform.position,near=camera.nearClipPlane,cutA=originalCut,cutB=Shader.GetGlobalVector("_MapCutB"),rockBounds=rm.bounds,points=new System.Collections.Generic.List<Point>()};
 foreach(var pixel in new[]{new Vector2(575,270),new Vector2(578,330),new Vector2(650,330),new Vector2(870,420),new Vector2(1050,470)})report.points.Add(Trace(camera,pixel,rock,originalCut));
 foreach(string mode in new[]{"base","no-rock","near003","no-shadows","no-normal","no-tunnel","no-cutaway","unlit-rock","clearance08","clearance16","frame-id","between-posts"}){
  rock.transform.position=originalPosition+new Vector3(mode=="clearance08"?-.08f:mode=="clearance16"?-.16f:0,0,0);rock.transform.localScale=Vector3.one*(mode=="between-posts"?.8f:1f);if(mode=="between-posts")rock.transform.position=new Vector3(originalPosition.x,0,11.13f);var selectedMaterials=tunnelMaterials.ToArray();if(mode=="frame-id")selectedMaterials[4]=frameId;tunnelRenderer.sharedMaterials=selectedMaterials;rock.SetActive(mode!="no-rock");camera.nearClipPlane=mode=="near003"?.003f:.03f;Shader.SetGlobalVector("_MapCutA",mode=="no-cutaway"?Vector4.zero:originalCut);foreach(var rr in renderers)rr.enabled=mode!="no-tunnel";
  for(int i=0;i<lights.Length;i++)lights[i].shadows=mode=="no-shadows"?LightShadows.None:shadows[i];rm.receiveShadows=mode!="no-shadows";
  Material temp=null;if(mode=="no-normal"){temp=new Material(originalMat);temp.DisableKeyword("_NORMALMAP");rm.sharedMaterial=temp;}else if(mode=="unlit-rock"){temp=new Material(Shader.Find("Universal Render Pipeline/Unlit"));temp.SetColor("_BaseColor",Color.white);rm.sharedMaterial=temp;}else rm.sharedMaterial=originalMat;
  var im=Shared117Review.Image(camera,1600,900);File.WriteAllBytes(Path.Combine(Out,mode+".png"),im.EncodeToPNG());UnityEngine.Object.DestroyImmediate(im);rm.sharedMaterial=originalMat;if(temp)UnityEngine.Object.DestroyImmediate(temp);
 }
 tunnelRenderer.sharedMaterials=tunnelMaterials;rock.transform.localScale=Vector3.one*.8f;rock.transform.position=new Vector3(originalPosition.x,0,11.13f);Shader.SetGlobalVector("_MapCutA",originalCut);foreach(var rr in renderers)rr.enabled=true;camera.transform.position=hero.position+new Vector3(0,9,-6.3f);camera.transform.LookAt(hero.position+Vector3.up*.5f);typeof(MapTunnels.MapTunnelCutaway).GetMethod("LateUpdate",BindingFlags.NonPublic|BindingFlags.Instance).Invoke(cut,null);var normalImage=Shared117Review.Image(camera,1600,900);File.WriteAllBytes(Path.Combine(Out,"between-posts-normal.png"),normalImage.EncodeToPNG());UnityEngine.Object.DestroyImmediate(normalImage);report.pass=true;File.WriteAllText(Path.Combine(Out,"diagnosis.json"),JsonUtility.ToJson(report,true));EditorApplication.Exit(0);
 }catch(Exception e){File.WriteAllText(Path.Combine(Out,"error.txt"),e.ToString());Debug.LogException(e);EditorApplication.Exit(1);}}
 [Serializable]class Hit{public string renderer,shader;public int triangle;public float distance,facing;public Vector3 point,normal;public Color colour;public bool cut,rock;}
 [Serializable]class Point{public Vector2 pixel;public Hit[] hits;}
 [Serializable]class Report{public bool pass;public Vector3 camera;public float near;public Vector4 cutA,cutB;public Bounds rockBounds;public System.Collections.Generic.List<Point> points;}
 static Point Trace(Camera camera,Vector2 pixel,GameObject rock,Vector4 cut){var ray=camera.ViewportPointToRay(new Vector3(pixel.x/1600f,1-pixel.y/900f,0));var hits=new System.Collections.Generic.List<Hit>();foreach(var filter in UnityEngine.Object.FindObjectsByType<MeshFilter>(FindObjectsSortMode.None)){var renderer=filter.GetComponent<Renderer>();if(!renderer||!renderer.enabled||!filter.sharedMesh)continue;var mesh=filter.sharedMesh;var pos=mesh.vertices;var colors=mesh.colors;var tris=mesh.triangles;var mat=renderer.sharedMaterial;for(int k=0;k<tris.Length;k+=3){var a=filter.transform.TransformPoint(pos[tris[k]]);var b=filter.transform.TransformPoint(pos[tris[k+1]]);var c=filter.transform.TransformPoint(pos[tris[k+2]]);var e1=b-a;var e2=c-a;var h=Vector3.Cross(ray.direction,e2);var det=Vector3.Dot(e1,h);if(Mathf.Abs(det)<1e-7f)continue;var inv=1/det;var s=ray.origin-a;var u=inv*Vector3.Dot(s,h);if(u<0||u>1)continue;var q=Vector3.Cross(s,e1);var v=inv*Vector3.Dot(ray.direction,q);if(v<0||u+v>1)continue;var d=inv*Vector3.Dot(e2,q);if(d<=0)continue;var p=ray.GetPoint(d);var n=Vector3.Cross(e1,e2).normalized;bool removed=false;if(mat.shader.name=="MapTunnels/Tunnel"&&cut.w>0&&p.y>cut.y+1.7f){var centre=new Vector3(cut.x,cut.y,cut.z);var ab=camera.transform.position-(centre+Vector3.up);float t=Mathf.Clamp01(Vector3.Dot(p-(centre+Vector3.up),ab)/Mathf.Max(ab.sqrMagnitude,1e-4f));removed=(mat.GetFloat("_Shaft")<.5f&&new Vector2(p.x-cut.x,p.z-cut.z).magnitude<cut.w)||(p-(centre+Vector3.up+ab*t)).magnitude<1.1f*(1+.4f*t);}
 hits.Add(new Hit{renderer=filter.name,shader=mat.shader.name,triangle=k/3,distance=d,point=p,normal=n,facing=Vector3.Dot(n,-ray.direction),colour=colors.Length==pos.Length?colors[tris[k]]*(1-u-v)+colors[tris[k+1]]*u+colors[tris[k+2]]*v:Color.white,cut=removed,rock=filter.gameObject==rock});}}
 return new Point{pixel=pixel,hits=hits.OrderBy(h=>h.distance).Take(14).ToArray()};}
}
